//! The fixtures in `fixtures/` parse, and the malformed ones fail with exact paths.
//!
//! The 300 and 10k Line Item fixtures are generated by this file. After
//! changing the generator, regenerate them with
//! `REGENERATE_FIXTURES=1 cargo test -p invoice-pdf-core --test fixtures`.

use std::fs;
use std::path::PathBuf;

use invoice_pdf_core::{InvoiceData, Layout, ValidationError, load};

fn fixture_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures")
        .join(name)
}

fn read_fixture(name: &str) -> String {
    let path = fixture_path(name);
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

fn load_fixtures(
    layout: &str,
    invoice_data: &str,
) -> Result<(Layout, InvoiceData), Vec<ValidationError>> {
    load(&read_fixture(layout), &read_fixture(invoice_data))
}

fn error_paths(layout: &str, invoice_data: &str) -> Vec<String> {
    match load_fixtures(layout, invoice_data) {
        Ok(_) => panic!("{layout} with {invoice_data} should be rejected"),
        Err(errors) => errors.into_iter().map(|error| error.path).collect(),
    }
}

// --- Valid fixtures ---------------------------------------------------------

#[test]
fn small_fixture_loads() {
    let (layout, invoice_data) =
        load_fixtures("layout.json", "invoice-data-small.json").expect("valid fixture");
    assert_eq!(layout.table.columns.len(), 6);
    assert_eq!(invoice_data.line_items.len(), 3);
    assert_eq!(
        invoice_data.header["recipient"],
        "Muster & Söhne KG\nz. Hd. Frau Groß\nHauptstraße 17\n54321 Beispielstadt"
    );
    assert_eq!(invoice_data.totals["gross"], "1.245,81 €");
    assert_eq!(invoice_data.giro_code.expect("giro code").amount, "1245.81");
}

#[test]
fn fixture_with_300_line_items_loads() {
    let (_, invoice_data) =
        load_fixtures("layout.json", "invoice-data-300.json").expect("valid fixture");
    assert_eq!(invoice_data.line_items.len(), 300);
    assert_eq!(invoice_data.line_items[299]["number"], "300");
}

#[test]
fn fixture_with_10k_line_items_loads() {
    let (_, invoice_data) =
        load_fixtures("layout.json", "invoice-data-10k.json").expect("valid fixture");
    assert_eq!(invoice_data.line_items.len(), 10_000);
    assert_eq!(invoice_data.line_items[9_999]["number"], "10000");
}

#[test]
fn generated_fixtures_are_up_to_date() {
    let regenerate = std::env::var_os("REGENERATE_FIXTURES").is_some();
    for (name, count, invoice_number) in [
        ("invoice-data-300.json", 300, "RE-2026-0300"),
        ("invoice-data-10k.json", 10_000, "RE-2026-9999"),
    ] {
        let expected = generate::invoice_data(count, invoice_number);
        let path = fixture_path(name);
        if regenerate {
            fs::write(&path, &expected).expect("write fixture");
        } else {
            assert!(
                read_fixture(name) == expected,
                "{name} is out of date; run `REGENERATE_FIXTURES=1 cargo test -p invoice-pdf-core --test fixtures`"
            );
        }
    }
}

// --- Malformed fixtures -----------------------------------------------------

#[test]
fn layout_with_invalid_boxes_reports_each_box() {
    assert_eq!(
        error_paths(
            "malformed/layout-invalid-boxes.json",
            "invoice-data-small.json"
        ),
        [
            "/layout/margins/top",
            "/layout/firstPageHeader/fields/2/size",
            "/layout/continuationHeader/fields/1/x",
            "/layout/table/columns/2/x",
            "/layout/footer/pageNumber/y",
        ]
    );
}

#[test]
fn layout_with_wrong_type_reports_its_path() {
    let errors = load_fixtures(
        "malformed/layout-wrong-type.json",
        "invoice-data-small.json",
    )
    .expect_err("malformed layout");
    assert_eq!(errors.len(), 1);
    assert_eq!(errors[0].path, "/layout/table/columns/2/source");
    assert!(
        errors[0].message.contains("invalid type: integer `3`"),
        "{}",
        errors[0].message
    );
}

#[test]
fn invoice_data_with_non_string_values_reports_each_path() {
    let errors = load_fixtures("layout.json", "malformed/invoice-data-non-string.json")
        .expect_err("malformed invoice data");
    let reported: Vec<_> = errors
        .iter()
        .map(|error| (error.path.as_str(), error.message.as_str()))
        .collect();
    assert_eq!(
        reported,
        [
            (
                "/invoiceData/header/invoiceDate",
                "expected a string, found a number"
            ),
            (
                "/invoiceData/lineItems/1/quantity",
                "expected a string, found a number"
            ),
            (
                "/invoiceData/lineItems/2/description",
                "expected a string, found null"
            ),
            (
                "/invoiceData/totals/gross",
                "expected a string, found an object"
            ),
            (
                "/invoiceData/giroCode/amount",
                "expected a string, found a number"
            ),
        ]
    );
}

#[test]
fn invoice_data_with_missing_and_unknown_keys_reports_each_path() {
    assert_eq!(
        error_paths("layout.json", "malformed/invoice-data-missing-keys.json"),
        [
            "/invoiceData/header/dueDate",
            "/invoiceData/header/orderNumber",
            "/invoiceData/lineItems/0/discount",
            "/invoiceData/lineItems/2/description",
            "/invoiceData/totals/tax",
        ]
    );
}

#[test]
fn invoice_data_with_syntax_error_reports_the_root() {
    let errors = load_fixtures("layout.json", "malformed/invoice-data-syntax-error.json")
        .expect_err("malformed invoice data");
    assert_eq!(errors.len(), 1);
    assert_eq!(errors[0].path, "/invoiceData");
    assert!(errors[0].message.contains("EOF"), "{}", errors[0].message);
}

/// Deterministic generator for the large Invoice Data fixtures.
mod generate {
    use std::fmt::Write;

    use serde_json::json;

    const DESCRIPTIONS: [&str; 7] = [
        "Schrauben M6 × 40, verzinkt",
        "Montage vor Ort",
        "Wartungsvertrag Klimaanlage, Quartalspauschale gemäß Vertrag Nr. 2026-117",
        "Kabelkanal weiß, 2 m",
        "Ersatzteil Lüfter\nSeriennummer 4711-0815-ÄÖÜ",
        "Anfahrt",
        "Prüfung nach DGUV V3 inkl. Prüfprotokoll und Prüfplakette für ortsveränderliche Geräte",
    ];
    const UNITS: [&str; 4] = ["Stk", "Std", "m", "psch"];

    /// Formats cents in German notation, e.g. `123456` → `"1.234,56 €"`.
    fn euro(cents: u64) -> String {
        let euros = (cents / 100).to_string();
        let mut grouped = String::new();
        for (i, digit) in euros.chars().enumerate() {
            if i > 0 && (euros.len() - i) % 3 == 0 {
                grouped.push('.');
            }
            grouped.push(digit);
        }
        format!("{grouped},{:02} €", cents % 100)
    }

    pub fn invoice_data(count: u64, invoice_number: &str) -> String {
        let mut line_items = String::new();
        let mut net = 0;
        for i in 1..=count {
            let quantity = i % 9 + 1;
            let unit_price = 250 + (i * 37) % 9000;
            let amount = quantity * unit_price;
            net += amount;
            let line_item = json!({
                "number": i.to_string(),
                "description": DESCRIPTIONS[(i % 7) as usize],
                "quantity": quantity.to_string(),
                "unit": UNITS[(i % 4) as usize],
                "unitPrice": euro(unit_price),
                "amount": euro(amount),
            });
            let separator = if i < count { "," } else { "" };
            writeln!(line_items, "    {line_item}{separator}").unwrap();
        }
        let tax = (net * 19 + 50) / 100;
        let gross = net + tax;

        let header = json!({
            "sender": "ACME GmbH · Musterstraße 1 · 12345 Musterstadt",
            "recipient": "Muster & Söhne KG\nz. Hd. Frau Groß\nHauptstraße 17\n54321 Beispielstadt",
            "invoiceNumber": invoice_number,
            "invoiceDate": "11.11.2026",
            "dueDate": "25.11.2026",
        });
        let totals = json!({ "net": euro(net), "tax": euro(tax), "gross": euro(gross) });
        let giro_code = json!({
            "beneficiaryName": "ACME GmbH",
            "iban": "DE89370400440532013000",
            "bic": "COBADEFFXXX",
            "amount": format!("{}.{:02}", gross / 100, gross % 100),
            "remittanceText": invoice_number,
        });
        format!(
            "{{\n  \"header\": {header},\n  \"lineItems\": [\n{line_items}  ],\n  \"totals\": {totals},\n  \"giroCode\": {giro_code}\n}}\n"
        )
    }

    #[test]
    fn euro_groups_thousands() {
        assert_eq!(euro(5), "0,05 €");
        assert_eq!(euro(123_456), "1.234,56 €");
        assert_eq!(euro(123_456_789), "1.234.567,89 €");
    }
}
